{"expected_revision_id": "77ac1c5a-0123-42d3-9979-7b44d1a35339", "source": "module TopModule (
    input  logic clk,
    input  logic L,
    input  logic q_in,
    input  logic r_in,
    output logic Q
);

    // 2:1 multiplexer: load r_in when L is high, otherwise take q_in
    logic d;
    assign d = L ? r_in : q_in;

    // D flip-flop with defined power-up value
    initial Q = 1'b0;

    always_ff @(posedge clk) begin
        Q <= d;
    end

endmodule
"}
